public class RenderMirror implements ISimpleBlockRenderingHandler {

	@Override
	public void renderInventoryBlock(Block block, int metadata, int modelId, RenderBlocks renderer) { }

	@Override
	public boolean renderWorldBlock(IBlockAccess world, int x, int y, int z, Block block, int modelId, RenderBlocks renderer) {

		Tessellator tessellator = Tessellator.instance;
		IIcon iicon = block.getIcon(0, world.getBlockMetadata(x, y, z));

		tessellator.setBrightness(block.getMixedBrightnessForBlock(world, x, y, z));
		tessellator.setColorOpaque_F(1, 1, 1);

		if(renderer.hasOverrideBlockTexture()) {
			iicon = renderer.overrideBlockTexture;
		}

		TileEntity te = world.getTileEntity(x, y, z);

		if(!(te instanceof TileEntitySolarMirror))
			return false;

		TileEntitySolarMirror mirror = (TileEntitySolarMirror) te;

		int dx = mirror.tX - mirror.xCoord;
		int dy = mirror.tY - mirror.yCoord;
		int dz = mirror.tZ - mirror.zCoord;

		tessellator.addTranslation(x + 0.5F, y, z + 0.5F);
		ObjUtil.renderPartWithIcon((HFRWavefrontObject) ResourceManager.solar_mirror, "Base", iicon, tessellator, 0, true);

		if(mirror.tY <= mirror.yCoord)
			ObjUtil.renderPartWithIcon((HFRWavefrontObject) ResourceManager.solar_mirror, "Mirror", iicon, tessellator, 0, true);
		else
			printMirror(iicon, dx, dy, dz);

		tessellator.addTranslation(-x - 0.5F, -y, -z - 0.5F);

		return true;
	}

	private void printMirror(IIcon icon, int dx, int dy, int dz) {

		ObjMesh.Part go = null;

		for(ObjMesh.Part obj : ((HFRWavefrontObject) ResourceManager.solar_mirror).getMesh().parts) {
			if(obj.name.equals("Mirror")) go = obj;
		}

		if(go == null) return;

		Tessellator tes = Tessellator.instance;

		double dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
		double pitch = -Math.asin(dy / dist) + Math.PI / 2D;
		double yaw = -Math.atan2(dz, dx) - Math.PI / 2D;

		for(ObjMesh.Face f : go.faces) {

			ObjMesh.Vec n = f.normal;

			tes.setNormal(n.x, n.y, n.z);
			float brightness = (n.y + 1) * 0.65F;

			if(brightness < 0.45F)
				brightness = 0.45F;

			tes.setColorOpaque_F(brightness, brightness, brightness);

			for(int i = 0; i < f.corners.size(); i++) {

				ObjMesh.Vec v = f.corners.get(i).position;

				com.hbm.util.Vec3NT vec = new com.hbm.util.Vec3NT(v.x, v.y - 1, v.z);
				vec.rotateAroundXRad((float) pitch);
				vec.rotateAroundYRad((float) yaw);

				float x = (float) vec.x;
				float y = (float) vec.y + 1;
				float z = (float) vec.z;

				ObjMesh.Vec t = f.corners.get(i).uv;
				tes.addVertexWithUV(x, y, z, icon.getInterpolatedU(t.x * 16), icon.getInterpolatedV(t.y * 16));

				if(i % 3 == 2)
					tes.addVertexWithUV(x, y, z, icon.getInterpolatedU(t.x * 16), icon.getInterpolatedV(t.y * 16));
			}
		}
	}

	@Override
	public boolean shouldRender3DInInventory(int modelId) {
		return false;
	}

	@Override
	public int getRenderId() {
		return SolarMirror.renderID;
	}

